INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(29590905, 'Super Junior Confrontation', '超级少年组对决！', 'スーパージュニア対決！', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽攻击宣言时发动。那个战斗无效，对方场上攻击力最低的1只表侧攻击表示怪兽和自己场上守备力最低的1只表侧守备表示怪兽进行战斗。那个战斗结束后，战斗阶段结束。'),
(66171432, 'Super Koi Koi', '超来来', '超こいこい', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「超来来」在1回合只能发动1张。 ①：从自己卡组上面把3张卡翻开，那之中的「花札卫」怪兽尽可能无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的等级变成2星，效果无效化。剩下的卡全部里侧表示除外，自己失去除外的卡数量×1000基本分。 ②：把墓地的这张卡除外，把自己场上1只怪兽解放才能发动。从手卡把1只「花札卫」怪兽无视召唤条件特殊召唤。'),
(48130397, 'Super Polymerization', '超融合', '超融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。 ①：丢弃1张手卡才能发动。自己·对方场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(72332074, 'Super Quantal Alphan Spike', '超级量子必杀 阿尔方杀球', '超量必殺アルファンボール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「超级量子战士」怪兽3种类以上存在的场合才能发动。对方场上的卡全部回到持有者卡组。那之后，对方从额外卡组把1只怪兽无视召唤条件特殊召唤。 ②：从自己墓地把这张卡和1只「超级量子妖精 阿尔方」除外才能发动。从卡组把1张「超级量子机舰 炎磁大母舰」发动。'),
(15721392, 'Super Quantal Alphancall Appeal', '超级量子要请 阿尔方呼救', '超量要請アルファンコール', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的「超级量子」怪兽被战斗破坏时才能发动。从额外卡组把1只「超级量子机兽」超量怪兽特殊召唤。那之后，可以从自己的手卡·卡组·墓地选在那张超量怪兽卡有卡名记述的1只「超级量子战士」怪兽效果无效特殊召唤。'),
(58753372, 'Super Quantal Fairy Alphan', '超级量子妖精 阿尔方', '超量妖精アルファン', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，以自己场上1只「超级量子」怪兽为对象才能发动。自己场上的全部怪兽的等级变成和作为对象的怪兽相同。 ②：把这张卡解放才能发动。从卡组把3只卡名不同的「超级量子」怪兽给对方观看，对方从那之中随机选1只。那1只在自己场上特殊召唤，剩余送去墓地。'),
(66646087, 'Super Quantal Fairy Zetan', '超级量子妖精 泽坦', '超量妖精ゼータン', 'Effect Monster', 'Zombie', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有「超级量子妖精 泽坦」以外的「超级量子」怪兽存在的场合才能发动。这张卡特殊召唤。那之后，可以把这张卡的等级变成和自己场上1只「超级量子」怪兽相同。 ②：把这张卡解放，从卡组把暗属性怪兽以外的1张「超级量子」卡送去墓地才能发动。从卡组把「超级量子妖精 泽坦」以外的1只「超级量子」怪兽特殊召唤。'),
(11646785, 'Super Quantal Mech Beast Aeroboros', '超级量子机兽 天翔衔尾蛇', '超量機獣エアロボロス', 'XYZ Monster', 'Machine', 'WIND', 4, 2200, 2400, '4星怪兽×2 ①：没有超量素材的这张卡不能攻击。 ②：1回合1次，把这张卡1个超量素材取除，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。这张卡有「超级量子战士 绿光层」在作为超量素材的场合，这个效果在对方回合也能发动。 ③：1回合1次，自己主要阶段才能发动。选自己的手卡·场上1只「超级量子战士」怪兽在这张卡下面重叠作为超量素材。'),
(85252081, 'Super Quantal Mech Beast Grampulse', '超级量子机兽 惊涛虎鲸', '超量機獣グランパルス', 'XYZ Monster', 'Machine', 'WATER', 3, 1800, 2800, '3星怪兽×2 ①：没有超量素材的这张卡不能攻击。 ②：1回合1次，把这张卡1个超量素材取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。这张卡有「超级量子战士 蓝光层」在作为超量素材的场合，这个效果在对方回合也能发动。 ③：1回合1次，自己主要阶段才能发动。选自己的手卡·场上1只「超级量子战士」怪兽在这张卡下面重叠作为超量素材。'),
(57450198, 'Super Quantal Mech Beast Lusterrex', '超级量子机兽 耀闪暴龙', '超量機獣ラスターレックス', 'XYZ Monster', 'Machine', 'LIGHT', 7, 2700, 1900, '7星怪兽×2 ①：没有超量素材的这张卡不能攻击。 ②：1回合1次，把这张卡1个超量素材取除，以场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这张卡有「超级量子战士 白光层」在作为超量素材的场合，这个效果在对方回合也能发动。 ③：1回合1次，自己主要阶段才能发动。从自己的手卡·场上选1只「超级量子战士」怪兽在这张卡下面重叠作为超量素材。'),
(57031794, 'Super Quantal Mech Beast Magnaliger', '超级量子机兽 炎皇狮虎', '超量機獣マグナライガー', 'XYZ Monster', 'Machine', 'FIRE', 5, 2600, 2000, '5星怪兽×2 ①：没有超量素材的这张卡不能攻击。 ②：1回合1次，把这张卡1个超量素材取除，以场上1只怪兽为对象才能发动。那只怪兽破坏。这张卡有「超级量子战士 红光层」在作为超量素材的场合，这个效果在对方回合也能发动。 ③：1回合1次，自己主要阶段才能发动。选自己的手卡·场上1只「超级量子战士」怪兽在这张卡下面重叠作为超量素材。'),
(84025439, 'Super Quantal Mech King Great Magnus', '超级量子机神王 超凡惊天煌', '超量機神王グレート・マグナス', 'XYZ Monster', 'Machine', 'LIGHT', 12, 3600, 3200, '12星怪兽×3 ①：得到这张卡的超量素材种类的以下效果。 ●2种类以上：1回合1次，自己·对方的主要阶段把这张卡1个超量素材取除才能发动。选场上1张卡回到卡组。 ●4种类以上：这张卡不受「超级量子」卡以外的卡的效果影响。 ●6种类以上：对方不能用卡的效果从卡组把卡加入手卡。 ②：这张卡被送去墓地的场合才能发动。从自己墓地选「超级量子机兽」超量怪兽3种类各1只特殊召唤。'),
(10424147, 'Super Quantal Mech Ship Magnacarrier', '超级量子机舰 惊天运输机', '超量機艦マグナキャリア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以自己场上1只「超级量子战士」怪兽为对象才能把这个效果发动。和那只自己怪兽相同属性的1只「超级量子机兽」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：把场地区域的这张卡送去墓地，以自己的场上·墓地的「超级量子机兽」超量怪兽3种类各1只为对象才能发动。从额外卡组把1只「超级量子机神王 大磁炎」特殊召唤，那下面把作为对象的怪兽和那些超量素材全部重叠作为超量素材。'),
(47819246, 'Super Quantal Mech Sword - Magnaslayer', '超级量子机神剑－惊天煌层叠斩', '超量機神剣－マグナスレイヤー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「超级量子」超量怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只怪兽装备。 ②：这张卡装备的怪兽攻击力上升那只怪兽的阶级数值×100，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：自己战斗阶段，把装备的这张卡送去墓地才能发动。这张卡装备过的怪兽在这个回合在同1次的战斗阶段中可以作3次攻击。'),
(1825445, 'Super Quantal Union - Magnaformation', '超级量子合神－惊天阵', '超量合神－マグナフォーメーション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己主要阶段1内，对方不能把场上的「超级量子」卡作为效果的对象。 ②：以自己场上1只「超级量子」超量怪兽为对象才能发动。选作为对象的怪兽以外的自己场上1只表侧表示怪兽在作为对象的怪兽下面重叠作为超量素材。'),
(92034192, 'Super Quantum Black Layer', '超级量子士 黑层', '超量士ブラックレイヤー', 'Effect Monster', 'Zombie', 'DARK', 7, 2400, 2400, '这个卡名的①②③的效果1回合各能使用1次。 ①：对方把怪兽的效果发动时才能发动。从自己手卡选1张其他卡丢弃，这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。把1只「超级量子机兽」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤，从自己墓地把1只「超级量子」怪兽作为那超量素材。 ③：这张卡被送去墓地的场合才能发动。从卡组把1张「超级量子」魔法卡加入手卡。'),
(12369277, 'Super Quantum Blue Layer', '超级量子士 蓝层', '超量士ブルーレイヤー', 'Effect Monster', 'Psychic', 'WATER', 3, 1200, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤时才能发动。从卡组把「超级量子战士 蓝光层」以外的1张「超级量子」卡加入手卡。 ②：这张卡被送去墓地的场合，以自己墓地最多3张「超级量子」卡为对象才能发动。那些卡回到卡组。'),
(85374678, 'Super Quantum Green Layer', '超级量子士 绿层', '超量士グリーンレイヤー', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1600, 1400, '「超级量子战士 绿光层」的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。从手卡把1只「超级量子」怪兽特殊召唤。 ②：这张卡被送去墓地的场合，把手卡1张「超级量子」卡丢弃才能发动。自己从卡组抽1张。'),
(59975920, 'Super Quantum Red Layer', '超级量子士 红层', '超量士レッドレイヤー', 'Effect Monster', 'Warrior', 'FIRE', 5, 2000, 800, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤时，以自己墓地1张「超级量子」卡为对象才能发动。那张卡加入手卡。 ③：这张卡被送去墓地的场合，以「超级量子战士 红光层」以外的自己墓地1只「超级量子」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽不能把效果发动。'),
(73422829, 'Super Quantum White Layer', '超级量子士 白层', '超量士ホワイトレイヤー', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2400, 2400, '这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只光属性以外的「超级量子」怪兽送去墓地才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡召唤·特殊召唤成功时才能发动。从卡组把1只「超级量子」怪兽送去墓地。这张卡的属性·等级变成和那只怪兽相同。 ③：这张卡被送去墓地的场合才能发动。从自己的卡组·墓地选1只「超级量子妖精 阿尔方」加入手卡。'),
(27770341, 'Super Rejuvenation', '超再生能力', '超再生能力', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这张卡发动的回合的结束阶段，自己从卡组抽出这个回合从自己手卡丢弃的龙族怪兽以及这个回合从自己的手卡·场上解放的龙族怪兽的数量。'),
(75923050, 'Super Robolady', '稀有金属女武神', 'レアメタル・ヴァルキリー', 'Fusion Monster', 'Machine', 'EARTH', 6, 1200, 500, '「稀有金属女郎」＋「稀有金属战士」 这张卡在给对方直接攻击的伤害计算时攻击力上升1000，上场上的这张卡可以和融合区的「稀有金属骑士」互换（这张卡特殊召唤的回合不可以互换。）'),
(1412158, 'Super Roboyarou', '稀有金属骑士', 'レアメタル・ナイト', 'Fusion Monster', 'Machine', 'EARTH', 6, 1200, 500, '「稀有金属女郎」＋「稀有金属战士」 这张卡在对怪兽的战斗伤害计算时，攻击力上升1000，在场上的这张卡可以和融合区的「稀有金属女武神」互换（这张卡特殊召唤的回合不可以互换。）'),
(48422921, 'Super Rush Headlong', '猪突猛进', '猪突猛進', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：宣言1个属性，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只自己的表侧表示怪兽和持有宣言的属性的对方怪兽进行战斗的场合，那次伤害步骤开始时那只对方怪兽破坏。'),
(32854013, 'Super Rush Recklessly', '猛突进', '猛突進', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只兽族怪兽破坏，选择对方场上存在的1只怪兽回到卡组。'),
(28529976, 'Super Solar Nutrient', '超营养太阳', '超栄養太陽', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把自己场上1只2星以下的植物族怪兽解放才能把这张卡发动。把持有解放的怪兽的等级＋3以下的等级的1只植物族怪兽从手卡·卡组特殊召唤。这张卡从场上离开时那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(73694478, 'Super Soldier Rebirth', '转生之超战士', '転生の超戦士', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「转生的超战士」在1回合只能发动1张。 ①：以自己场上1只「混沌战士」怪兽为对象才能发动。那只怪兽送去墓地，和那只怪兽卡名不同的1只「混沌战士」怪兽无视召唤条件从手卡特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「混沌战士」怪兽为对象才能发动。那张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(14094090, 'Super Soldier Ritual', '超战士的仪式', '超戦士の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「混沌战士」仪式怪兽的降临必需。「超战士的仪式」的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把等级合计直到8的怪兽解放，从手卡把1只「混沌战士」仪式怪兽仪式召唤。 ②：从自己墓地把这张卡以及1只光属性怪兽和1只暗属性怪兽除外才能发动。从手卡把1只「混沌战士」仪式怪兽无视召唤条件特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(799183, 'Super Soldier Shield', '超战士之盾', '超戦士の盾', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「混沌战士」怪兽存在，场上的怪兽为对象的怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的场合，把自己场上1个魔力指示物取除才能发动。墓地的这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(79234734, 'Super Soldier Soul', '超战士之魂', '超戦士の魂', 'Effect Monster', 'Warrior', 'EARTH', 1, NULL, NULL, '「超战士之魂」的①②的效果1回合各能使用1次。 ①：把手卡1只「混沌战士」怪兽送去墓地才能发动。这张卡直到下次的对方结束阶段攻击力变成3000，卡名当作「混沌战士」使用。 ②：把墓地的这张卡除外才能发动。从卡组把1只「开辟之骑士」或者「宵暗之骑士」加入手卡。'),
(45948430, 'Super Soldier Synthesis', '超战士的萌芽', '超戦士の萌芽', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「混沌战士」仪式怪兽的降临必需。「超战士的萌芽」在1回合只能发动1张。 ①：等级合计直到8的以下其中1个组合的怪兽送去墓地，从自己的手卡·墓地把1只「混沌战士」仪式怪兽仪式召唤。 ●手卡1只光属性怪兽和卡组1只暗属性怪兽 ●手卡1只暗属性怪兽和卡组1只光属性怪兽'),
(93039339, 'Super Starslayer TY-PHON - Sky Crisis', '神兵灾星－厄咒弑 堤・丰', '厄災の星ティ・フォン', 'XYZ Monster', 'Fiend', 'DARK', 12, 2900, 2900, '12星怪兽×2 这张卡在对方从额外卡组把2只以上的怪兽特殊召唤的回合以及那下个回合也能在自己场上的攻击力最高的怪兽上面重叠来超量召唤。这个方法特殊召唤过的回合，自己不能把怪兽召唤·特殊召唤。 ①：只要超量召唤的这张卡在怪兽区域存在，双方不能把攻击力3000以上的怪兽的效果发动。 ②：1回合1次，把这张卡1个超量素材取除才能发动。场上1只怪兽回到手卡。'),
(81193865, 'Super Strident Blaze', '永恒进化冲击波', 'エターナル・エヴォリューション・バースト', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '机械族融合怪兽才能装备。 ①：只要这张卡在魔法与陷阱区域存在，自己战斗阶段中对方不能把魔法·陷阱·怪兽的效果发动。 ②：装备怪兽向对方怪兽攻击的伤害步骤结束时，从自己墓地把1只「电子龙」怪兽除外才能发动。装备怪兽向对方怪兽可以继续攻击。这个效果发动的回合，装备怪兽以外的自己怪兽不能攻击。'),
(8608979, 'Super Team Buddy Force Unite!', '一族之集结', '一族の結集', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。从自己的手卡·墓地选和那只怪兽是原本卡名不同并是原本种族相同的1只怪兽特殊召唤。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。从卡组选1张「一族的集结」在自己的魔法与陷阱区域盖放。'),
(17745969, 'Super Vehicroid - Mobile Base', '超级交通机人-移动基地', 'スーパービークロイド－モビルベース', 'Fusion Monster', 'Machine', 'EARTH', 10, NULL, 5000, '「机人」融合怪兽＋「机人」怪兽 这个卡名的①的效果1回合只能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。把持有那只怪兽的攻击力以下的攻击力的1只「机人」怪兽从卡组·额外卡组特殊召唤。 ②：自己·对方的结束阶段以这张卡以外的自己的主要怪兽区域1只「机人」怪兽为对象才能发动。那只自己怪兽回到持有者手卡，这张卡的位置向那个怪兽区域移动。'),
(3897065, 'Super Vehicroid - Stealth Union', '超级交通机人-隐形合体', 'スーパービークロイド－ステルス・ユニオン', 'Fusion Monster', 'Machine', 'EARTH', 9, 3600, 3000, '「卡车机人」＋「特快机人」＋「钻头机人」＋「隐形机人」 1回合1次，自己的主要阶段时可以选择场上存在的1只机械族以外的怪兽，当作装备卡使用给这张卡装备。因这个效果有怪兽装备的场合，可以向对方场上的全部怪兽各作1次攻击。这张卡攻击的场合，这张卡的原本攻击力变成一半数值。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(36256625, 'Super Vehicroid Jumbo Drill', '超级交通机人-巨大钻头', 'スーパービークロイド－ジャンボドリル', 'Fusion Monster', 'Machine', 'EARTH', 8, 3000, 2000, '「蒸汽机人」＋「钻头机人」＋「潜艇机人」 这只怪兽的融合召唤只能用上记的卡进行。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(33951077, 'Super War-Lion', '超级战狮', 'スーパー・ウォー・ライオン', 'Ritual Monster', 'Beast', 'EARTH', 7, 2300, 2100, '「狮子的仪式」降临。'),
(6849042, 'Super-Ancient Dinobeast', '超古代恐兽', '超古代恐獣', 'Effect Monster', 'Dinosaur', 'EARTH', 8, 2700, 1400, '这张卡可以把1只恐龙族怪兽解放表侧攻击表示上级召唤。 ①：这张卡在怪兽区域存在，从自己墓地有恐龙族怪兽特殊召唤时才能发动。自己从卡组抽1张。'),
(20529766, 'Super-Electromagnetic Voltech Dragon', '超电磁稼动伏特龙', '超電磁稼動ボルテック・ドラゴン', 'Effect Monster', 'Thunder', 'LIGHT', 5, 2400, 1000, '用以下的怪兽为祭品作祭品召唤的场合，这张卡得到各自的效果。 ●电池人-单1型：以这1张卡为对象的魔法·陷阱卡的效果无效。 ●电池人-单2型：这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。 ●电池人-单3型：这张卡攻击力上升1000。'),
(5220687, 'Super-Nimble Mega Hamster', '迅捷大仓鼠', '素早いビッグハムスター', 'Flip Effect Monster', 'Beast', 'EARTH', 4, 1100, 1800, '反转：可以从自己卡组把1只3星以下的兽族怪兽里侧守备表示特殊召唤。'),
(64463828, 'Superalloy Beast Raptinus', '超合魔兽 拉普提诺斯', '超合魔獣ラプテノス', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2200, 2200, '二重怪兽×2 ①：只要这张卡在怪兽区域存在，场上的二重怪兽当作再1次召唤的状态使用。'),
(88307361, 'Superancient Deepsea King Coelacanth', '超古深海王 空棘鱼', '超古深海王シーラカンス', 'Effect Monster', 'Fish', 'WATER', 7, 2800, 2200, '①：1回合1次，丢弃1张手卡才能发动。从卡组把4星以下的鱼族怪兽尽可能特殊召唤。这个效果特殊召唤的怪兽不能攻击宣言，效果无效化。 ②：场上的这张卡为对象的魔法·陷阱·怪兽的效果发动时，把这张卡以外的自己场上1只鱼族怪兽解放才能发动。那个效果无效并破坏。'),
(97705809, 'Supercharge', '增压', 'スーパーチャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的怪兽只有机械族「机人」怪兽的场合，对方怪兽的攻击宣言时才能发动。自己从卡组抽2张。'),
(66523544, 'Superdimensional Robot Galaxy Destroyer', '超次元机器人 银河毁灭者', '超次元ロボ ギャラクシー・デストロイヤー', 'XYZ Monster', 'Machine', 'LIGHT', 10, 5000, 2000, '10星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除才能发动（对方不能对应这个效果的发动把魔法·陷阱卡发动）。对方场上的魔法·陷阱卡全部破坏。'),
(38354018, 'Superdreadnought Rail Cannon Flying Launcher', NULL, NULL, 'XYZ Monster', 'Machine', 'EARTH', 10, 3800, 3000, NULL),
(56910167, 'Superdreadnought Rail Cannon Gustav Max', '超重型炮塔列车 古斯塔夫超大炮', '超弩級砲塔列車グスタフ・マックス', 'XYZ Monster', 'Machine', 'EARTH', 10, 3000, 3000, '10星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。给与对方2000伤害。'),
(92359409, 'Superdreadnought Rail Cannon Gustav Rocket', NULL, NULL, 'XYZ Monster', 'Machine', 'EARTH', 10, 5000, 3000, NULL),
(26096328, 'Superdreadnought Rail Cannon Juggernaut Liebe', '超重型炮塔列车 爱恋倾城炮', '超弩級砲塔列車ジャガーノート・リーベ', 'XYZ Monster', 'Machine', 'EARTH', 11, 4000, 4000, '11星怪兽×3 「超重型炮塔列车 破天巨爱」1回合1次也能在自己场上的机械族·10阶的超量怪兽上面重叠来超量召唤。 ①：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力·守备力上升2000。这个效果的发动后，直到回合结束时自己不用这张卡不能攻击宣言。 ②：这张卡在同1次的战斗阶段中可以向怪兽作出最多有这张卡的超量素材数量＋1次的攻击。'),
(9402966, 'Superheavy Samurai Battleball', '超重武者 球魂－C', '超重武者タマ－C', 'Tuner Monster', 'Machine', 'DARK', 2, 100, 800, '「超重武者 魂-C」的效果1回合只能使用1次。 ①：自己场上没有「超重武者」怪兽以外的怪兽存在，自己墓地没有魔法·陷阱卡存在的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡从场上送去墓地。那之后，把持有和送去墓地的那2只怪兽的原本等级合计相同等级的1只「超重武者」同调怪兽从额外卡组当作同调召唤作特殊召唤。'),
(85528209, 'Superheavy Samurai Beast Kyubi', '超重魔兽 九尾－B', '超重魔獣キュウ－B', 'Synchro Monster', 'Machine', 'EARTH', 9, 1900, 2500, '调整＋调整以外的「超重武者」怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：自己墓地没有魔法·陷阱卡存在的场合，这张卡的守备力上升对方场上的特殊召唤的怪兽数量×900。'),
(3117804, 'Superheavy Samurai Big Benkei', '超重武者 大弁庆－K', '超重武者ビッグベン－K', 'Effect Monster', 'Machine', 'EARTH', 8, 1000, 3500, '①：这张卡召唤·特殊召唤成功时才能发动。这张卡的表示形式变更。 ②：只要这张卡在怪兽区域存在，自己的「超重武者」怪兽可以用表侧守备表示的状态作出攻击。那个场合，那怪兽用守备力当作攻击力使用进行伤害计算。'),
(36523152, 'Superheavy Samurai Big Waraji', '超重武者 大草屦－G', '超重武者ビッグワラ－G', 'Effect Monster', 'Machine', 'EARTH', 5, 800, 1800, '①：自己墓地没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功的回合，自己不是「超重武者」怪兽不能特殊召唤。 ②：机械族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(7864030, 'Superheavy Samurai Blowtorch', '超重武者 松明-2', '超重武者タイマ－２', 'Effect Monster', 'Machine', 'EARTH', 1, 500, 300, '①：对方怪兽的攻击宣言时自己墓地没有魔法·陷阱卡存在的场合，把这张卡从手卡送去墓地，以自己场上1只「超重武者」怪兽为对象才能发动。攻击对象转移为那只怪兽进行伤害计算。 ②：1回合1次，对方怪兽的攻击宣言时才能发动。攻击对象转移为这张卡进行伤害计算。 ③：这张卡不会被战斗破坏。'),
(41628550, 'Superheavy Samurai Blue Brawler', '超重武者 鬼若-O2', '超重武者ワカ－O２', 'Effect Monster', 'Machine', 'EARTH', 4, NULL, 2000, '①：这张卡召唤·特殊召唤成功时才能发动。这张卡的表示形式变更。 ②：这张卡不会被战斗破坏。'),
(64193046, 'Superheavy Samurai Brave Masurawo', '超重天神 益荒男－O', '超重天神マスラ－O', 'Synchro Monster', 'Machine', 'EARTH', 12, 2100, 4000, '调整＋调整以外的怪兽1只以上 这个卡名在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：自己场上的「超重武者」怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1张「超重武者」卡破坏。 ③：1回合1次，对方把魔法·陷阱卡的效果发动的场合才能发动。自己直到手卡变成3张为止从卡组抽卡。'),
(90587641, 'Superheavy Samurai Commander Shanawo', '超重神将 遮那王－O', '超重神将シャナ－O', 'Synchro Pendulum Effect Monster', 'Machine', 'DARK', 8, 2000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：这张卡是已同调召唤的场合，1回合1次，自己·对方的战斗阶段才能发动。从自己墓地以及自己的魔法与陷阱区域的表侧表示的卡之中选1张「超重武者」怪兽卡特殊召唤。那之后，可以把这张卡在自己的灵摆区域放置。'),
(87535691, 'Superheavy Samurai Drum', '超重武者 鼓－３', '超重武者ツヅ－３', 'Tuner Monster', 'Machine', 'EARTH', 1, 300, 300, '「超重武者 鼓-3」的效果1回合只能使用1次。 ①：场上的这张卡被破坏送去墓地的场合，以「超重武者 鼓-3」以外的自己墓地1只「超重武者」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(71386411, 'Superheavy Samurai Fist', '超重武者 拳－C', '超重武者コブ－C', 'Tuner Monster', 'Machine', 'EARTH', 2, 900, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「超重武者」怪兽战斗破坏对方怪兽的自己战斗阶段才能发动。用包含这张卡的自己场上的怪兽为同调素材作同调召唤。 ②：自己墓地没有魔法·陷阱卡存在的场合，以自己场上1只「超重武者」同调怪兽为对象才能发动。那只怪兽的等级下降1星，这张卡从墓地特殊召唤。这个效果的发动后，直到回合结束时自己不是「超重武者」怪兽不能特殊召唤。'),
(27978707, 'Superheavy Samurai Flutist', '超重武者 影法师－C', '超重武者カゲボウ－C', 'Effect Monster', 'Machine', 'EARTH', 3, 500, 1000, '「超重武者 影法师-C」的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从手卡把1只「超重武者」怪兽特殊召唤。 ②：自己场上的「超重武者」怪兽成为效果的对象时，把墓地的这张卡除外才能发动。那个发动无效并破坏。这个效果在对方回合也能发动。'),
(78274190, 'Superheavy Samurai General Coral', '超重辉将 珊瑚－５', '超重輝将サン－５', 'Pendulum Effect Monster', 'Machine', 'EARTH', 1, 300, 500, '这张卡在规则上也当作「超重武者」卡使用。「超重辉将 珊瑚-5」的怪兽效果1回合只能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合，把自己场上最多2只「超重武者」怪兽解放才能发动。自己从卡组抽出解放的数量。'),
(42880485, 'Superheavy Samurai General Jade', '超重辉将 翡翠－E', '超重輝将ヒス－E', 'Pendulum Effect Monster', 'Machine', 'EARTH', 8, 1800, 2800, '这张卡在规则上也当作「超重武者」卡使用。这张卡可以把1只「超重武者」怪兽解放作上级召唤。 ①：这张卡召唤·特殊召唤成功时才能发动。这张卡的表示形式变更。 ②：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。'),
(62017867, 'Superheavy Samurai Gigagloves', '超重武者 手套－V', '超重武者グロウ－V', 'Effect Monster', 'Machine', 'EARTH', 3, 100, 1000, '①：自己墓地没有魔法·陷阱卡存在，这张卡被送去墓地的场合才能发动。从卡组上面把5张卡确认，用喜欢的顺序回到卡组上面。 ②：对方怪兽的直接攻击宣言时，把墓地的这张卡除外才能发动。自己卡组最上面的卡翻开，那张卡是「超重武者」怪兽的场合加入手卡，那只攻击怪兽的攻击力变成0。不是的场合把翻开的卡送去墓地。'),
(44891812, 'Superheavy Samurai Helper', '超重武者 御助-K', '超重武者オタス－K', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '①：自己墓地没有魔法·陷阱卡存在的场合，自己的守备表示怪兽和对方怪兽进行战斗的伤害计算时把这张卡从手卡丢弃，以进行战斗的怪兽以外的自己场上1只「超重武者」怪兽为对象才能发动。那只进行战斗的自己怪兽的守备力只在那次伤害计算时上升作为对象的怪兽的守备力数值。 ②：对方怪兽的直接攻击宣言时，把墓地的这张卡除外，以自己墓地1只「超重武者」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(41307269, 'Superheavy Samurai Kabuto', '超重武者 兜-10', '超重武者カブ－１０', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 2000, '①：对方对怪兽的特殊召唤成功的场合才能发动。自己场上的攻击表示的「超重武者」怪兽全部变成守备表示，那个守备力直到回合结束时上升500。'),
(89091772, 'Superheavy Samurai Magnet', '超重武者 磁石－Q', '超重武者ジシャ－Q', 'Effect Monster', 'Machine', 'EARTH', 4, 900, 1900, '①：这张卡召唤成功时才能发动。从手卡把1只4星以下的「超重武者」怪兽特殊召唤。那之后，这张卡变成守备表示。 ②：只要这张卡在怪兽区域存在，对方不能向其他怪兽攻击。'),
(19510093, 'Superheavy Samurai Monk Big Benkei', '超重僧兵 大弁庆－K', '超重僧兵ビッグベン－K', 'Pendulum Effect Monster', 'Machine', 'EARTH', 8, 1000, 3500, '这个卡名在规则上也当作「超重武者」卡使用。这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合才能发动。从手卡·卡组把1只「超重武者 大弁庆-K」送去墓地，这张卡从手卡特殊召唤。 ②：这张卡作为同调素材表侧表示加入额外卡组的场合才能发动。这张卡在自己的灵摆区域放置。'),
(83334932, 'Superheavy Samurai Motorbike', '超重武者 摩托－Q', '超重武者バイ－Q', 'Tuner Monster', 'Machine', 'EARTH', 2, 800, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合，把这张卡从手卡丢弃才能发动。从卡组把「超重武者 摩托-Q」以外的1只「超重武者」怪兽加入手卡。 ②：1回合1次，以自己场上1只机械族怪兽为对象才能发动。那只怪兽的等级上升2星。'),
(76471944, 'Superheavy Samurai Ninja Sarutobi', '超重忍者 猿飞－B', '超重忍者サルト－B', 'Synchro Monster', 'Machine', 'EARTH', 8, 2000, 2800, '机械族调整＋调整以外的「超重武者」怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：1回合1次，自己墓地没有魔法·陷阱卡存在的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏，给与对方500伤害。这个效果在对方回合也能发动。'),
(36953371, 'Superheavy Samurai Ogre Shutendoji', '超重神鬼 酒吞童子－G', '超重神鬼シュテンドウ－G', 'Synchro Monster', 'Machine', 'EARTH', 6, 500, 2500, '机械族调整1只＋调整以外的「超重武者」怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：自己墓地没有魔法·陷阱卡存在，这张卡同调召唤成功时才能发动。对方场上的魔法·陷阱卡全部破坏。'),
(15495787, 'Superheavy Samurai Prepped Defense', '超重武者 心构-A', '超重武者ココロガマ－A', 'Effect Monster', 'Machine', 'EARTH', 3, 100, 2100, '自己墓地有魔法·陷阱卡存在的场合，这张卡不能召唤·反转召唤。 ①：自己墓地没有魔法·陷阱卡存在，自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡在这个回合不会被战斗·效果破坏。'),
(82112494, 'Superheavy Samurai Prodigy Wakaushi', '超重神童 若牛－U４', '超重神童ワカ－U４', 'Pendulum Tuner Effect Monster', 'Machine', 'DARK', 4, 1000, 1500, '这个卡名在规则上也当作「超重武者」卡使用。这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合，从手卡丢弃1只怪兽才能发动。从手卡·卡组把1只「超重武者」怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是「超重武者」怪兽不能特殊召唤。 ②：这张卡作为同调素材表侧表示加入额外卡组的场合才能发动。这张卡在自己的灵摆区域放置。'),
(78391364, 'Superheavy Samurai Scales', '超重武者 天平B－N', '超重武者テンB－N', 'Effect Monster', 'Machine', 'EARTH', 4, 800, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：对方场上有怪兽2只以上存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合，以「超重武者 天秤B-N」以外的自己墓地1只4星以下的「超重武者」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(33918636, 'Superheavy Samurai Scarecrow', '超重武者 稻草人－C', '超重武者カカ－C', 'Link Monster', 'Machine', 'EARTH', NULL, NULL, NULL, '「超重武者」怪兽1只 这个卡名的②的效果1回合只能使用1次。这张卡不能作为连接素材。 ①：自己墓地没有魔法·陷阱卡存在的场合，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：自己墓地没有魔法·陷阱卡存在的场合，从手卡丢弃1只怪兽，以自己墓地1只「超重武者」怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。'),
(5182107, 'Superheavy Samurai Security', '超重武者 同心C－N', '超重武者ドウC－N', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的额外卡组（表侧）把1只机械族灵摆怪兽加入手卡。 ②：自己墓地没有魔法·陷阱卡存在的场合，把这张卡解放才能发动。除「超重武者 同心C-N」外的1只攻击力1500以下的机械族·地属性怪兽从自己的手卡·墓地特殊召唤。'),
(3064425, 'Superheavy Samurai Soulbang Cannon', '超重武者装魂 大爆炸', '超重武者装留ビッグバン', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 1000, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。自己的手卡·场上的这只怪兽当作守备力上升1000的装备卡使用给那只怪兽装备。 ②：自己场上有守备表示的「超重武者」怪兽存在，对方在战斗阶段把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个发动无效并破坏。那之后，场上的怪兽全部破坏，双方玩家受到1000伤害。'),
(27756115, 'Superheavy Samurai Soulbeads', '超重武者装留 死返', '超重武者装留マカルガエシ', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽1回合只有1次不会被效果破坏。 ③：守备表示怪兽被战斗破坏送去自己墓地时，把这张卡从手卡送去墓地才能发动。那怪兽攻击表示特殊召唤。'),
(77679716, 'Superheavy Samurai Soulbreaker Armor', '超重武者装留 破坏铠', '超重武者装留ブレイク・アーマー', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, 500, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。自己的手卡·场上的这只怪兽当作守备力下降1000的装备卡使用给那只自己怪兽装备。装备怪兽不会被战斗破坏。 ②：自己主要阶段，从自己墓地把包含这张卡的「超重武者装留 破坏铠」全部除外，以守备力比原本守备力低的1只「超重武者」怪兽为对象才能发动。给与对方那只怪兽的守备力和那个原本守备力的相差数值的伤害。'),
(35800511, 'Superheavy Samurai Soulbuster Gauntlet', '超重武者装魂 爆裂手甲', '超重武者装留バスター・ガントレット', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, 400, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作守备力上升400的装备卡使用给那只自己怪兽装备。 ②：自己墓地没有魔法·陷阱卡存在的场合，自己的守备表示的「超重武者」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡送去墓地才能发动。那只进行战斗的自己怪兽的守备力直到回合结束时变成原本守备力的2倍。'),
(40028305, 'Superheavy Samurai Soulclaw', '超重武者装魂 光爪', '超重武者装留シャイン・クロー', 'Effect Monster', 'Machine', 'EARTH', 2, 500, 500, '「超重武者装留 光爪」的②的效果1回合只能使用1次。 ①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作攻击力·守备力上升500的装备卡使用给那只自己怪兽装备。装备怪兽不会被战斗破坏。 ②：这张卡的效果让这张卡装备中的场合才能发动。装备的这张卡特殊召唤。'),
(4786063, 'Superheavy Samurai Soulfire Suit', '超重武者装魂 火焰铠甲', '超重武者装留ファイヤー・アーマー', 'Effect Monster', 'Machine', 'FIRE', 2, 800, 800, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。装备怪兽的等级变成5星。 ②：把这张卡从手卡丢弃，以自己场上1只守备表示的「超重武者」怪兽为对象才能发动。直到回合结束时，那只怪兽的守备力下降800，不会被战斗·效果破坏。这个效果在对方回合也能发动。'),
(56727340, 'Superheavy Samurai Soulgaia Booster', '超重武者装魂 盖亚推进器', '超重武者装留ガイア・ブースター', 'Effect Monster', 'Machine', 'EARTH', 4, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作装备卡使用给那只自己怪兽装备。装备怪兽当作调整使用。 ②：自己墓地没有魔法·陷阱卡存在，这张卡的效果让这张卡装备中的场合才能发动。这张卡特殊召唤。'),
(14624296, 'Superheavy Samurai Soulhorns', '超重武者装魂 双角', '超重武者装留ダブル・ホーン', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, 300, '「超重武者装留 双角」的②的效果1回合只能使用1次。 ①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。装备怪兽在同1次的战斗阶段中可以作2次攻击。 ②：这张卡的效果让这张卡装备中的场合才能发动。装备的这张卡特殊召唤。'),
(95500396, 'Superheavy Samurai Soulpeacemaker', '超重武者装魂 仲裁', '超重武者装留チュウサイ', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '「超重武者装留 仲裁」的③的效果1回合只能使用1次。 ①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：这张卡的效果让这张卡装备中的场合，对方不能向装备怪兽以外的自己怪兽攻击。 ③：把用这张卡的效果把这张卡装备的自己怪兽解放才能发动。从卡组把1只「超重武者」怪兽特殊召唤。'),
(90361010, 'Superheavy Samurai Soulpiercer', '超重武者装魂 岩融', '超重武者装留イワトオシ', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, NULL, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作装备卡使用给那只自己怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把「超重武者装留 岩融」以外的1只「超重武者」怪兽加入手卡。'),
(31181711, 'Superheavy Samurai Soulshield Wall', '超重武者装留 巨壁', '超重武者装留グレート・ウォール', 'Effect Monster', 'Machine', 'EARTH', 3, 1200, 1200, '①：自己主要阶段以自己场上1只「超重武者」怪兽为对象才能发动。从自己的手卡·场上把这只怪兽当作守备力上升1200的装备卡使用给那只自己怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽被选择作为攻击对象时，把装备的这张卡送去墓地才能发动。那次攻击无效，装备怪兽的守备力变成0。'),
(50065971, 'Superheavy Samurai Stealth Ninja', '超重忍者 忍足－A・C', '超重忍者シノビ－A・C', 'Synchro Monster', 'Machine', 'EARTH', 7, 1200, 2800, '机械族调整＋调整以外的机械族怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：自己墓地没有魔法·陷阱卡存在的场合才能发动。这张卡的原本守备力直到回合结束时变成一半，这个回合这张卡可以直接攻击。 ③：这张卡被效果破坏送去墓地的场合，下次的准备阶段才能发动。这张卡从墓地特殊召唤。'),
(10333641, 'Superheavy Samurai Stealthy', '超重武者 隐秘－３２', '超重武者オン－３２', 'Effect Monster', 'Machine', 'EARTH', 1, 200, 700, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。 ②：自己墓地没有魔法·陷阱卡存在的场合，把这张卡解放，以对方墓地1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡从场上离开的场合除外。这个效果在对方回合也能发动。'),
(17775525, 'Superheavy Samurai Steam Train King', '超重蒸鬼 铁道王－O', '超重蒸鬼テツドウ－O', 'Synchro Monster', 'Machine', 'EARTH', 12, 2000, 4800, '「超重武者」调整＋调整以外的「超重武者」怪兽2只以上 这个卡名在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：1回合1次，把最多2张手卡丢弃，以丢弃数量的对方场上的卡为对象才能发动。那些卡破坏。 ③：1回合1次，自己主要阶段才能发动。双方墓地的魔法·陷阱卡全部除外，给与对方除外数量×200伤害。'),
(75988594, 'Superheavy Samurai Swordmaster Musashi', '超重剑圣 武藏－C', '超重剣聖ムサ－C', 'Synchro Monster', 'Machine', 'EARTH', 5, 300, 2300, '调整＋调整以外的怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡同调召唤成功时，以自己墓地1只机械族怪兽为对象才能发动。那只怪兽加入手卡。自己墓地有魔法·陷阱卡存在的场合，这个回合自己不能把那只怪兽以及那些同名怪兽召唤·特殊召唤。 ②：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。'),
(77013169, 'Superheavy Samurai Swordsman', '超重武者 刀狩-999', '超重武者ソード－９９９', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 1800, '①：这张卡召唤·特殊召唤成功时才能发动。这张卡的表示形式变更。 ②：自己场上的「超重武者」怪兽和对方怪兽进行战斗的伤害计算后发动。那只对方怪兽的攻击力·守备力变成0。'),
(14756848, 'Superheavy Samurai Thief', '超重武者 盗人－１０', '超重武者ヌス－１０', 'Effect Monster', 'Machine', 'EARTH', 10, 1000, 1000, '①：自己墓地没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功的回合，自己不是「超重武者」怪兽不能特殊召唤。 ②：可以把这张卡解放，从以下效果选择1个发动。 ●选对方的魔法与陷阱区域1张卡破坏。那之后，可以把破坏的那张魔法·陷阱卡在自己场上盖放。 ●选对方的灵摆区域1张卡破坏。那之后，可以把破坏的那张卡在自己的灵摆区域放置。'),
(41141943, 'Superheavy Samurai Transporter', '超重武者 飞脚－Q', '超重武者ヒキャ－Q', 'Effect Monster', 'Machine', 'EARTH', 5, 1200, 1800, '「超重武者 飞脚-Q」的②的效果1回合只能使用1次。 ①：自己墓地没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功的回合，自己不是「超重武者」怪兽不能特殊召唤。 ②：自己墓地没有魔法·陷阱卡存在的场合，把这张卡解放才能发动。从手卡把最多2只怪兽在对方场上守备表示特殊召唤。那之后，自己从卡组抽出这个效果特殊召唤的怪兽的数量。'),
(64373401, 'Superheavy Samurai Trumpeter', '超重武者 法螺贝－E', '超重武者ホラガ－E', 'Tuner Monster', 'Machine', 'EARTH', 2, 300, 600, '①：自己墓地没有魔法·陷阱卡存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功的回合，自己不是「超重武者」怪兽不能特殊召唤。 ②：自己墓地没有魔法·陷阱卡存在，把这张卡解放对「超重武者」怪兽的上级召唤成功的场合才能发动。这张卡从墓地特殊召唤。'),
(34496660, 'Superheavy Samurai Wagon', '超重武者 大八－８', '超重武者ダイ－８', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, 1800, '「超重武者 大八-8」的③的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功时才能发动。这张卡的表示形式变更。 ②：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ③：自己墓地没有魔法·陷阱卡存在的场合才能发动。自己场上的表侧守备表示的这张卡变成攻击表示，从卡组把1只「超重武者装留」怪兽加入手卡。'),
(494922, 'Superheavy Samurai Warlord Susanowo', '超重荒神 须佐之男－O', '超重荒神スサノ－O', 'Synchro Monster', 'Machine', 'EARTH', 10, 2400, 3800, '机械族调整＋调整以外的「超重武者」怪兽1只以上 这张卡在规则上也当作「超重武者」卡使用。 ①：这张卡可以用表侧守备表示的状态作出攻击。那个场合，这张卡用守备力当作攻击力使用进行伤害计算。 ②：1回合1次，自己墓地没有魔法·陷阱卡存在的场合，以对方墓地1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡从场上离开的场合除外。这个效果在对方回合也能发动。'),
(53363708, 'Supermagic Sword of Raptinus', '拉普帝诺斯的超魔剑', 'ラプテノスの超魔剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的表示形式的以下效果适用。 ●攻击表示：装备怪兽不会成为对方的效果的对象。 ●守备表示：装备怪兽不会被战斗破坏。 ②：自己·对方的战斗阶段开始时才能发动。装备怪兽的表示形式变更，把1只怪兽召唤。'),
(16165939, 'Supernatural Danger Zone', '超自然警戒区域', '超自然警戒区域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：效果怪兽以外的怪兽表侧表示特殊召唤的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。从自己的手卡·卡组·墓地选效果怪兽以外的1只怪兽特殊召唤。'),
(49980185, 'Supernatural Regeneration', '超能力治疗', '超能力治療', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡在结束阶段时才能发动。自己回复这个回合送去墓地的念动力族怪兽数量×1000的数值的基本分。'),
(93918159, 'Supersoaring', '超越天翔', '超越天翔', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从双方墓地的怪兽以及除外中的怪兽之中以1只恐龙族怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(63804806, 'Supersonic Skull Flame', '速度之王☆骷髅炎鬼', 'スピード・キング☆スカル・フレイム', 'Effect Monster', 'Zombie', 'WIND', 10, 2600, 2000, '这张卡不能通常召唤。把自己墓地存在的1只「骷髅炎鬼」从游戏中除外的场合可以特殊召唤。1回合1次，可以给与对方基本分自己墓地存在的「燃烧骷髅头」数量×400的数值的伤害。此外，这张卡从场上送去墓地时，可以把自己墓地存在的1只「骷髅炎鬼」特殊召唤。'),
(95750695, 'Supervise', '超二重召唤', 'スーペルヴィス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '二重怪兽才能装备。 ①：装备怪兽当作再1次召唤的状态使用。 ②：表侧表示的这张卡从场上送去墓地的场合，以自己墓地1只通常怪兽为对象发动。那只怪兽特殊召唤。'),
(44072894, 'Supply', '物资调达员', '物資調達員', 'Flip Effect Monster', 'Warrior', 'EARTH', 4, 1300, 800, '反转：通过「融合」而送去自己的墓地的2只融合素材怪兽加入手卡。'),
(23738096, 'Supply Soldier of the Indestructible Insects', '无死虫团的补给兵', '無死虫団の補給兵', 'Effect Monster', 'Insect', 'EARTH', 5, 600, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：昆虫族怪兽的效果发动时才能发动。这张卡从手卡特殊召唤。连锁对方的效果的发动把这个效果发动的场合，再把那个效果无效。这个效果的发动后，直到下次的自己回合的结束时自己不是昆虫族怪兽不能从额外卡组特殊召唤。 ②：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只昆虫族融合怪兽融合召唤。'),
(17626381, 'Supply Squad', '补给部队', '補給部隊', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上的怪兽被战斗·效果破坏的场合发动。自己抽1张。'),
(41422426, 'Supporter in the Shadows', '阴暗处的协力者', '物陰の協力者', 'Normal Monster', 'Warrior', 'EARTH', 3, 1000, 1000, '从暗处协助他人的可爱小人。'),
(92176681, 'Suppression Collider', '压制碰撞者', 'サプレス・コライダー', 'Normal Monster', 'Cyberse', 'DARK', 8, 2800, 2600, '与网络世界的巨恶交战的熟练斗士。凡是被其铁锤压缩的数据，谁都不能复原。'),
(98380593, 'Supremacy Berry', '至高的果实', '至高の木の実', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡的发动时，自己基本分比对方低的场合，自己回复2000基本分。自己基本分比对方高的场合，自己受到1000分伤害。'),
(21113684, 'Supreme Arcanite Magician', '霸魔导士 奥金魔导师', '覇魔導士アーカナイト・マジシャン', 'Fusion Monster', 'Spellcaster', 'LIGHT', 10, 1400, 2800, '魔法师族同调怪兽＋魔法师族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡融合召唤成功的场合发动。给这张卡放置2个魔力指示物。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×1000。 ③：1回合1次，可以把自己场上1个魔力指示物取除，从以下效果选择1个发动。 ●以场上1张卡为对象才能发动。那张卡破坏。 ●自己从卡组抽1张。'),
(70771599, 'Supreme King Dragon Clear Wing', '霸王眷龙 清透翼', '覇王眷竜クリアウィング', 'Synchro Monster', 'Dragon', 'DARK', 8, 2500, 2000, '调整＋调整以外的暗属性灵摆怪兽1只以上 ①：这张卡同调召唤的场合才能发动。对方场上的表侧表示怪兽全部破坏。 ②：1回合1次，这张卡和对方怪兽进行战斗的伤害计算前才能发动。那只怪兽破坏，给与对方破坏的怪兽的原本攻击力数值的伤害。 ③：这张卡在墓地存在的场合，把自己场上2只「霸王眷龙」怪兽解放才能发动。这张卡特殊召唤。'),
(42160203, 'Supreme King Dragon Dark Rebellion', '霸王眷龙 暗反叛', '覇王眷竜ダーク・リベリオン', 'XYZ Monster', 'Dragon', 'DARK', 4, 2500, 2000, '暗属性4星灵摆怪兽×2 ①：1回合1次，这张卡和对方怪兽进行战斗的伤害计算前，把这张卡1个超量素材取除才能发动。直到回合结束时，那只对方怪兽的攻击力变成0，这张卡的攻击力上升那个原本攻击力数值。 ②：自己·对方的战斗阶段，让这张卡回到额外卡组才能发动。从自己的额外卡组（表侧）把「霸王眷龙」灵摆怪兽或「霸王门」灵摆怪兽合计最多2只守备表示特殊召唤。'),
(69610326, 'Supreme King Dragon Darkwurm', '霸王眷龙 暗黑亚龙', '覇王眷竜ダークヴルム', 'Pendulum Effect Monster', 'Dragon', 'DARK', 4, 1800, 1200, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「霸王门」灵摆怪兽加入手卡。 ②：这张卡在墓地存在，自己场上没有怪兽存在的场合才能发动。这张卡特殊召唤。'),
(41908872, 'Supreme King Dragon Lightwurm', '霸王眷龙 光明亚龙', '覇王眷竜ライトヴルム', 'Pendulum Tuner Effect Monster', 'Dragon', 'LIGHT', 4, 1200, 1800, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的额外卡组（表侧）把1只「霸王眷龙」灵摆怪兽或「霸王门」灵摆怪兽加入手卡。那之后，可以进行1只「霸王眷龙」同调怪兽的同调召唤或者1只「霸王眷龙」超量怪兽的超量召唤。 ②：这张卡在额外卡组表侧存在的状态，自己场上的表侧表示的灵摆怪兽被战斗·效果破坏的场合才能发动。这张卡加入手卡。'),
(96733134, 'Supreme King Dragon Odd-Eyes', '霸王眷龙 异色眼', '覇王眷竜オッドアイズ', 'Pendulum Effect Monster', 'Dragon', 'DARK', 8, 2500, 2000, '①：把自己场上2只「霸王眷龙」怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：自己的灵摆怪兽和对方怪兽进行战斗的场合，给与对方的战斗伤害变成2倍。 ③：自己·对方的战斗阶段把这张卡解放才能发动。从自己的额外卡组（表侧）把「霸王眷龙 异色眼」以外的「霸王眷龙」灵摆怪兽或「霸王门」灵摆怪兽合计最多2只守备表示特殊召唤。'),
(43387895, 'Supreme King Dragon Starving Venom', '霸王眷龙 凶饿猛毒', '覇王眷竜スターヴ・ヴェノム', 'Fusion Monster', 'Dragon', 'DARK', 8, 2800, 2000, '暗属性灵摆怪兽×2 这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己场上的上记的卡解放的场合可以从额外卡组特殊召唤。 ①：1回合1次，以这张卡以外的自己或对方的场上·墓地1只怪兽为对象才能发动。这张卡直到结束阶段得到和那只怪兽的原本的卡名·效果相同的卡名·效果。这个回合，自己怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(22211622, 'Supreme King Gate Infinity', '霸王门 无限', '覇王門無限', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, NULL, NULL, '①：1回合1次，以这张卡以外的自己场上1张表侧表示卡为对象才能发动。那张卡和这张卡破坏，把1只龙族超量怪兽或者龙族灵摆怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0，效果无效化，不能作为同调·超量召唤的素材。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(14513273, 'Supreme King Gate Magician', '霸王门的魔术师', '覇王門の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 7, 2500, 2000, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己的灵摆区域有「霸王门之魔术师」以外的「霸王门」卡存在的场合才能发动。从手卡·额外卡组把「灵摆龙」「超量龙」「同调龙」「融合龙」怪兽之内1只送去墓地，这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。除魔法师族怪兽外的1张有「霸王龙 扎克」的卡名记述的卡从卡组加入手卡。'),
(96227613, 'Supreme King Gate Zero', '霸王门 零', '覇王門零', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, NULL, NULL, '①：1回合1次，以这张卡以外的自己场上1张表侧表示卡为对象才能发动。那张卡和这张卡破坏，把1只龙族融合怪兽或者龙族同调怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0，效果无效化，不能作为同调·超量召唤的素材。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(13331639, 'Supreme King Z-ARC', '霸王龙扎克', '覇王龍ズァーク', 'Pendulum Effect Fusion Monster', 'Dragon', 'DARK', 12, 4000, 4000, '龙族的融合·同调·超量·灵摆怪兽各1只合计4只 这张卡不用融合召唤不能特殊召唤。 ①：这张卡特殊召唤的场合发动。对方场上的卡全部破坏。 ②：这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ③：这张卡战斗破坏对方怪兽时才能发动。从卡组·额外卡组把1只「霸王眷龙」怪兽特殊召唤。 ④：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(48654267, 'Supreme King Z-ARC - Synchro Universe', '霸王龙 扎克-同调宇宙', '覇王龍ズァーク－シンクロ・ユニバース', 'Synchro Pendulum Effect Monster', 'Dragon', 'DARK', 12, 4000, 4000, '调整＋调整以外的暗属性灵摆怪兽1只以上 ①：这张卡只要在怪兽区域存在，卡名当作「霸王龙 扎克」使用。 ②：这张卡战斗破坏对方怪兽的伤害计算后或者给与对方战斗伤害时才能发动。从自己的卡组·额外卡组·墓地把最多2只「霸王眷龙」怪兽守备表示特殊召唤。 ③：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(72043279, 'Supreme King''s Castle', '霸王城', '覇王城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己对用「暗黑融合」的效果才能特殊召唤的融合怪兽用「暗黑融合」的效果以外也能融合召唤。 ②：1回合1次，自己的恶魔族怪兽和对方怪兽进行战斗的伤害计算时，从卡组·额外卡组把1只「邪心英雄」怪兽送去墓地才能发动。那只自己怪兽的攻击力直到回合结束时上升送去墓地的怪兽的等级×200。'),
(84869738, 'Supreme Rage', '霸王之逆鳞', '覇王の逆鱗', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「霸王龙 扎克」存在的场合才能发动。「霸王龙 扎克」以外的自己场上的怪兽全部破坏，从自己的手卡·卡组·额外卡组·墓地把最多4只卡名不同的「霸王眷龙」怪兽无视召唤条件特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只「霸王眷龙」超量怪兽为对象才能发动。从自己的额外卡组（表侧）·墓地选2只「霸王眷龙」怪兽作为成为对象的怪兽的超量素材。'),
(31259606, 'Supreme Sea Mare', '绝海之泌泪', '絶海のマーレ', 'Effect Monster', 'Aqua', 'WATER', 4, 1500, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「绝海之马雷」以外的1只水族怪兽送去墓地。 ②：自己结束阶段，把这张卡解放，以「绝海之马雷」以外的自己墓地1只水族怪兽为对象才能发动。那只怪兽加入手卡。'),
(31042659, 'Supreme Sovereign Serpent of Golgonda', '霸蛇大公 戈尔钢达', '覇蛇大公ゴルゴンダ', 'Effect Monster', 'Reptile', 'FIRE', 8, -1, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己的场地区域有表侧表示卡存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：只要场上有「大沙海 黄金戈尔工达」存在，这张卡的原本攻击力变成3000。 ③：场上的「大沙海 黄金戈尔工达」被效果破坏的场合，可以作为代替把自己墓地1只怪兽除外。'),
(33057951, 'Surface', '浮上', '浮上', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只3星以下的鱼族·海龙族·水族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(55697723, 'Surfacing Big Jaws', '浮上水面的大口鲛', '浮上するビッグ・ジョーズ', 'Effect Monster', 'Fish', 'WATER', 4, 1800, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：魔法卡发动的回合的自己主要阶段才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只鱼族「鲨」怪兽加入手卡。 ③：把这张卡在水属性怪兽的超量召唤使用的场合，可以把这张卡的等级当作3星或5星使用。'),
(33331231, 'Surgical Striker - H.A.M.P.', '闪术兵器－H.A.M.P.', '閃術兵器－H.A.M.P.', 'Effect Monster', 'Machine', 'DARK', 8, 2500, 2500, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「闪刀姬」怪兽存在的场合，这张卡可以把自己或者对方场上1只怪兽解放，从手卡往那个控制者场上特殊召唤。 ②：这张卡被战斗破坏时，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(23530726, 'Surgical Striker - S.P.E.C.T.R.A.', '闪术兵器－S.P.E.C.T.R.A.', '閃術兵器－S.P.E.C.T.R.A.', 'Link Monster', 'Machine', 'DARK', NULL, 3000, NULL, '包含连接怪兽的怪兽2只以上 这个卡名在规则上也当作「闪刀姬」卡使用。这张卡不用连接召唤不能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：连锁2以后对方把魔法·陷阱·怪兽的效果发动时，从自己的手卡·墓地把2张魔法卡除外才能发动。那个效果无效。那之后，可以把对方场上1张卡破坏。 ②：自己墓地没有魔法卡存在的场合，这张卡的攻击力下降3000。'),
(70491413, 'Surprise Chain', '惊心供应链', 'サプライズ・チェーン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：同一连锁上没有复数次同名卡的效果发动的场合，那个连锁2以后才能发动。这张卡的发动时积累的连锁数量的以下效果适用。 ●2个以上：把这张卡的发动时积累的连锁数量的卡从自己卡组上面翻开，用喜欢的顺序回到卡组上面。 ●3个以上：从自己卡组上面把1张卡送去墓地。 ●4个以上：自己从卡组抽1张。'),
(35167375, 'Surprise Fusion', '惊喜结合', 'サプライズ・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只表侧表示怪兽为对象，宣言种族和属性各1个才能发动。那只怪兽变成宣言的种族·属性。那之后，可以把包含那只怪兽的自己场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ②：把墓地的这张卡除外才能发动。自己场上1只融合怪兽解放，把持有和那个等级相同等级的2只「惊喜衍生物」（魔法师族·暗·攻/守0）在自己场上特殊召唤。'),
(58419204, 'Survival Instinct', '生存本能', '生存本能', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地存在的任意数量的恐龙族怪兽从游戏中除外。每除外1只恐龙族怪兽，自己回复400基本分。'),
(58272005, 'Survival of the Fittest', '生存竞争', '生存競争', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只恐龙族怪兽为对象才能把这张卡发动。这张卡当作攻击力上升1000的装备卡使用给那只自己的恐龙族怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽攻击破坏对方怪兽送去墓地时才能发动。装备怪兽向对方怪兽只再1次可以继续攻击。'),
(44612603, 'Survival''s End', '生存境界', '生存境界', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的通常怪兽全部破坏，把最多有破坏数量的4星以下的恐龙族怪兽从卡组往自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。 ②：把墓地的这张卡除外，以自己场上1只恐龙族怪兽和对方场上1张卡为对象才能发动。那些卡破坏。'),
(40473581, 'Susa Soldier', '雷帝神', '雷帝神', 'Spirit Monster', 'Thunder', 'EARTH', 4, 2000, 1600, '这张卡不能特殊召唤。召唤·反转回合的结束阶段时回到主人的手卡。这张卡给与对方玩家的战斗伤害减半。'),
(62173132, 'Susurrus of the Sinful Spoils', '罪宝的私语', '罪宝の囁き', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只幻想魔族·魔法师族怪兽为对象才能发动。那只表侧表示怪兽回到手卡·额外卡组。那之后，自己的墓地·除外状态的1只幻想魔族·魔法师族怪兽特殊召唤。 ②：这张卡为让怪兽的效果发动而被送去墓地的场合才能发动。这张卡在自己场上盖放。'),
(70083592, 'Suture Rebirth', '缝合苏生', '縫合蘇生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「缝合苏生」在1回合只能发动1张。 ①：以自己墓地1只「毛绒动物」怪兽或者「魔玩具」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(77060848, 'Svartalf of the Nordic Alfar', '极星灵 暗精灵', '極星霊デックアールヴ', 'Tuner Monster', 'Spellcaster', 'DARK', 5, 1400, 1600, '这张卡召唤成功时，可以选择自己墓地存在的1只名字带有「极星」的怪兽加入手卡。'),
(10651797, 'Swallow Flip', '燕返', 'ツバメ返し', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '特殊召唤成功时发动的效果怪兽的效果的发动无效并破坏。'),
(5993144, 'Swallow''s Cowrie', '燕贝', 'スワローズ・カウリー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己的手卡·场上（表侧表示）1只鸟兽族怪兽解放才能发动。等级和解放的怪兽相同的1只鸟兽族怪兽从卡组加入手卡。'),
(94145683, 'Swallow''s Nest', '燕巢', 'スワローズ・ネスト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示的鸟兽族怪兽解放才能发动。和解放的怪兽相同等级的1只鸟兽族怪兽从卡组特殊召唤。'),
(79972330, 'Swallowtail Butterspy', '幻蝶刺客 凤蝶', '幻蝶の刺客アゲハ', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1200, '这张卡以外的自己场上的怪兽给与对方基本分战斗伤害时，选择对方场上表侧表示存在的1只怪兽发动。选择的怪兽的攻击力下降那个时候给与的伤害的数值。'),
(40453765, 'Swamp Battleguard', '野蛮人2号', 'バーバリアン２号', 'Effect Monster', 'Warrior', 'EARTH', 5, 1800, 1500, '①：自己场上的「野蛮人1号」每有1只，这张卡的攻击力上升500。'),
(50277973, 'Swamp Mirrorer', '镜像沼泽人', '鏡像のスワンプマン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：宣言种族和属性各1个才能把这张卡发动。这张卡变成持有宣言的种族·属性的通常怪兽（4星·攻1800/守1000）在怪兽区域特殊召唤（也当作陷阱卡使用）。'),
(30968774, 'Swap Cleric', '交换祭司', 'スワップリースト', 'Effect Monster', 'Cyberse', 'EARTH', 2, 500, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为连接素材送去墓地的场合才能发动。这张卡为连接素材的连接怪兽的攻击力下降500。那之后，自己从卡组抽1张。'),
(9126351, 'Swap Frog', '鬼青蛙', '鬼ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 1000, 500, '①：这张卡可以从手卡把这张卡以外的1只水属性怪兽丢弃，从手卡特殊召唤。 ②：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从卡组以及自己场上的表侧表示怪兽之中选1只2星以下的水族·水属性怪兽送去墓地。 ③：1回合1次，让自己场上1只怪兽回到持有者手卡才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把「鬼青蛙」以外的1只「青蛙」怪兽召唤。'),
(6116731, 'Swarm of Centipedes', '蜈蚣的进军', 'ムカデの進軍', 'Effect Monster', 'Insect', 'DARK', 3, 1500, 500, '这个卡名的②的效果1回合只能使用1次。 ①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转的场合，以场上1只其他怪兽为对象才能发动。那只怪兽变成表侧攻击表示或里侧守备表示。'),
(41039846, 'Swarm of Crows', '乌鸦巨群', 'カラスの巨群', 'Effect Monster', 'Winged Beast', 'DARK', 5, 1200, 1800, '这张卡不能从卡组特殊召唤。这张卡1回合只有1次可以变成里侧守备表示。这张卡反转召唤成功时，对方手卡随机丢弃1张。'),
(41872150, 'Swarm of Locusts', '蝗虫的军势', 'イナゴの軍勢', 'Effect Monster', 'Insect', 'DARK', 3, 1000, 500, '这张卡1个回合可以有1次变回里侧守备表示。这张卡反转召唤成功时，破坏对方场上1张魔法·陷阱卡。'),
(15383415, 'Swarm of Scarabs', '圣甲虫群', 'スカラベの大群', 'Effect Monster', 'Insect', 'DARK', 3, 500, 1000, '这张卡1个回合可以有1次变回里侧守备表示。这张卡反转召唤成功时，破坏对方场上1只怪兽。'),
(74983881, 'Sweet Corn', '小玉米', 'モロコシーナ', 'Effect Monster', 'Plant', 'EARTH', 2, NULL, NULL, '1回合1次，自己的主要阶段2支付500基本分才能发动。在自己场上把1只「玉米粒衍生物」（植物族·地·1星·攻/守0）特殊召唤。'),
(44843954, 'Sweet Dreams, Nemleria', '妮梦雷莉娅的寐梦', '寝姫の甘い夢', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「妮穆蕾莉娅」怪兽加入手卡。自己的额外卡组有表侧表示的「梦见之妮穆蕾莉娅」存在的场合，再在这个回合在「妮穆蕾莉娅」怪兽的召唤·特殊召唤成功时让对方不能把魔法·陷阱·怪兽的效果发动。 ②：让墓地的这张卡回到卡组最下面，以自己场上1张「梦见之妮穆蕾莉娅」为对象才能发动。那张卡表侧表示加入持有者的额外卡组。'),
(36848764, 'Sweet Roommaid', '甜蜜房务女仆', 'スウィートルームメイド', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己或者对方的手卡·卡组有卡被送去墓地的场合，以自己或者对方的墓地1张卡为对象才能发动。那张卡回到持有者卡组。'),
(81896370, 'Swift Birdman Joe', '疾风鸟人 乔', '疾風鳥人ジョー', 'Effect Monster', 'Winged Beast', 'WIND', 6, 2300, 1400, '用风属性怪兽为祭品作祭品召唤成功的场合，场上的魔法·陷阱卡全部回到持有者手卡。'),
(16589042, 'Swift Gaia the Fierce Knight', '疾风暗黑骑士盖亚', '疾風の暗黒騎士ガイア', 'Effect Monster', 'Warrior', 'DARK', 7, 2300, 2100, '①：手卡只有这1张卡的场合，这张卡可以不用解放作召唤。'),
(71934924, 'Swift Samurai Storm!', '疾风！凶杀阵', '疾風！凶殺陣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上名字带有「六武众」的怪兽进行过战斗的场合，直到这个回合的结束阶段时自己场上名字带有「六武众」的怪兽的攻击力上升300。'),
(18964575, 'Swift Scarecrow', '速攻稻草人', '速攻のかかし', 'Effect Monster', 'Machine', 'EARTH', 1, NULL, NULL, '①：对方回合的直接攻击宣言时，把这张卡从手卡丢弃才能发动。那次攻击无效。那之后，战斗阶段结束。'),
(84613836, 'Swiftstrike Armor', '神速之具足', '神速の具足', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的抽卡阶段时抽到的卡是名字带有「六武众」的怪兽卡的场合，可以把那张卡给对方观看并在自己场上特殊召唤。'),
(96765646, 'Swing of Memories', '回忆的秋千', '思い出のブランコ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只通常怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(47961342, 'Switch Point', '转轨地点', '転轍地点', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽3只以上存在的场合，选那之内的1只。对方必须把以下其中任意种送去墓地。 ●选的怪兽 ●选的怪兽以外的自身场上的全部怪兽'),
(300104005, 'Switcheroo', NULL, NULL, 'Skill Card', 'Keith', NULL, NULL, NULL, NULL, NULL),
(30426226, 'Switcheroroo', '对调英雄', 'スウィッチヒーロー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方场上的怪兽数量相同的场合，那些怪兽的控制权全部交换。'),
(13069066, 'Sword Arm of Dragon', '剑龙', '剣竜', 'Normal Monster', 'Dinosaur', 'EARTH', 6, 1750, 2030, '全身都附有刀刺的恐龙。以突进为手段进行攻击。'),
(64689404, 'Sword Breaker', '刀剑破坏者', 'ソードブレイカー', 'XYZ Monster', 'Warrior', 'EARTH', 6, 2700, 1000, '6星怪兽×2 1回合1次，把这张卡1个超量素材取除，宣言1个种族才能发动。这张卡和宣言的种族的怪兽进行战斗的场合，不进行伤害计算把那只怪兽破坏。'),
(51345461, 'Sword Hunter', '狩剑猎人', 'ソードハンター', 'Effect Monster', 'Warrior', 'EARTH', 7, 2450, 1700, '这张卡战斗破坏怪兽的战斗阶段结束时，墓地存在的那些怪兽作为攻击力上升200点的装备卡装备在这张卡上。'),
(81336148, 'Sword Master', '剑圣', 'ソード・マスター', 'Tuner Monster', 'Warrior', 'EARTH', 3, 1200, NULL, '自己场上存在的战士族怪兽的攻击没让对方怪兽破坏的伤害步骤结束时，这张卡可以从手卡特殊召唤。此外，这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(37120512, 'Sword of Dark Destruction', '暗之破神剑', '闇の破神剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '暗属性的怪兽才能装备。装备的怪兽攻击力上升400，守备力下降200。'),
(17589298, 'Sword of Dark Rites', '纳祭之剑', 'サクリファイス・ソード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '暗属性怪兽才能装备。装备怪兽的攻击力上升400。装备怪兽被作为祭品让这张卡送去墓地的场合，这张卡回到手卡。'),
(98495314, 'Sword of Deep-Seated', '执念之剑', '執念の剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备的怪兽攻击力·守备力上升500。这张卡送去墓地时，回到卡组最上面。'),
(61405855, 'Sword of Dragon''s Soul', '杀龙剑', '竜殺しの剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族怪兽才能装备。 ①：装备怪兽的攻击力上升700。 ②：装备怪兽和龙族怪兽进行战斗的伤害计算后发动。和装备怪兽进行战斗的那只怪兽在那次战斗阶段结束时破坏。'),
(48716139, 'Sword of Kusanagi', '草薙剑', '草薙剣', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '灵魂怪兽才能装备。装备怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。装备怪兽从自己场上回到手卡让这张卡被送去墓地时，这张卡回到手卡。'),
(48447192, 'Sword of Sparkles', '剑之辉煌', '剣の煌き', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「X-剑士」的怪兽才能装备。装备怪兽战斗破坏对方怪兽的场合，可以把对方场上存在的1张卡破坏。此外，可以把自己场上存在的1只怪兽解放，自己墓地存在的这张卡回到卡组最上面。'),
(5371656, 'Sword of the Soul-Eater', '食魂的魔刀', '魂喰らいの魔刀', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这张卡只能装备在自己场上存在的3星以下的通常怪兽身上。这张卡发动时，祭掉自己场上除装备这张卡的怪兽以外的所有通常怪兽（衍生物除外）。每祭掉1只通常怪兽，装备这张卡的怪兽攻击力上升1000点。'),
(35844557, 'Sword Ryzeal', '剑极・雷热涡炉', 'ソード・ライゼオル', 'Effect Monster', 'Thunder', 'FIRE', 4, 1500, 200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己的场上或墓地有「雷火沸动」怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只炎族·光属性怪兽加入手卡。'),
(73911410, 'Sword Slasher', '杀人机器', 'キラー・マシーン', 'Normal Monster', 'Machine', 'DARK', 5, 1450, 1500, '挥舞着大弯刀的狂暴杀人机器。'),
(25067275, 'Swords at Dawn', '旗鼓堂堂', '旗鼓堂々', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己墓地1张装备魔法卡和作为那个正确对象的场上1只怪兽才能发动。选择的装备魔法卡给选择的怪兽装备。这个效果装备的装备魔法卡在结束阶段时破坏。这张卡发动过的回合，自己不能把怪兽特殊召唤。「旗鼓堂堂」在1回合只能发动1张。'),
(93087299, 'Swords of Burning Light', '炎之护封剑', '炎の護封剣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合，对方场上的怪兽不能攻击宣言。自己场上有怪兽存在的场合或者对方手卡是5张以上的场合，这张卡破坏。'),
(12923641, 'Swords of Concealing Light', '暗之护封剑', '闇の護封剣', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第2次的自己准备阶段破坏。 ①：作为这张卡的发动时的效果处理，对方场上有表侧表示怪兽存在的场合，那些怪兽全部变成里侧守备表示。 ②：只要这张卡在魔法与陷阱区域存在，对方场上的怪兽不能把表示形式变更。'),
(72302403, 'Swords of Revealing Light', '光之护封剑', '光の護封剣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动后继续留在场上，用对方回合计算的3回合后的对方结束阶段破坏。 ①：作为这张卡的发动时的效果处理，对方场上有里侧表示怪兽存在的场合，那些全部变成表侧表示。 ②：只要这张卡在魔法与陷阱区域存在，对方怪兽不能攻击宣言。'),
(85255550, 'Swordsman from a Distant Land', '异国的剑士', '異国の剣士', 'Effect Monster', 'Warrior', 'EARTH', 1, 250, 250, '受到「异国的剑士」攻击的怪兽，5回合后被破坏。'),
(3573512, 'Swordsman of Landstar', '地星剑士', 'ランドスターの剣士', 'Normal Monster', 'Warrior', 'EARTH', 3, 500, 1200, '虽然剑术不太成熟，但却有不可思议力量的妖精剑士。'),
(64605089, 'Swordsman of Revealing Light', '护封剑之剑士', '護封剣の剣士', 'Effect Monster', 'Warrior', 'LIGHT', 8, NULL, 2400, '①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。那之后，特殊召唤的这张卡的守备力比那只攻击怪兽的攻击力高的场合，那只攻击怪兽破坏。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡1回合只有1次不会被战斗破坏。'),
(78836195, 'Swordsoul Assessment', '瑞相剑究', '瑞相剣究', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。从自己墓地把最多5张「相剑」卡或者幻龙族怪兽除外，作为对象的怪兽的攻击力上升除外数量×300。 ②：这张卡被除外的场合才能发动。在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(29884951, 'Swordsoul Auspice Chunjun', '相剑瑞兽－纯钧', '相剣瑞獣－純鈞', 'Effect Monster', 'Wyrm', 'EARTH', 6, 2400, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把自己场上1只怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：自己的幻龙族怪兽和从额外卡组特殊召唤的对方怪兽进行战斗的伤害计算前才能发动。那只对方怪兽和这张卡破坏。 ③：这张卡作为同调素材送去墓地的场合，以自己或者对方的场上·墓地1张卡为对象才能发动。那张卡除外。'),
(14821890, 'Swordsoul Blackout', '相剑暗转', '相剣暗転', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只幻龙族怪兽和对方场上2张卡为对象才能发动。那些卡破坏。 ②：这张卡被除外的场合才能发动。在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(56465981, 'Swordsoul Emergence', '龙相剑现', '龍相剣現', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「相剑」怪兽加入手卡。自己场上有同调怪兽存在的场合，也能作为代替把1只幻龙族怪兽加入手卡。 ②：这张卡被除外的场合，以自己场上1只「相剑」怪兽或者幻龙族怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升或者下降1星。'),
(69248256, 'Swordsoul Grandmaster - Chixiao', '相剑大师－赤霄', '相剣大師－赤霄', 'Synchro Monster', 'Wyrm', 'LIGHT', 8, 2800, 1000, '调整＋调整以外的幻龙族怪兽1只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡同调召唤的场合才能发动。从卡组选1张「相剑」卡加入手卡或除外。 ②：自己·对方回合，从自己的手卡·墓地把1张「相剑」卡或者1只幻龙族怪兽除外，以场上1只其他的效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(20001443, 'Swordsoul of Mo Ye', '相剑师－莫邪', '相剣師－莫邪', 'Effect Monster', 'Wyrm', 'WATER', 4, 1700, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，把手卡1张「相剑」卡或者1只幻龙族怪兽给对方观看才能发动。在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。自己抽1张。'),
(56495147, 'Swordsoul of Taia', '相剑师－泰阿', '相剣師－泰阿', 'Effect Monster', 'Wyrm', 'WIND', 4, 1800, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1张「相剑」卡或者1只幻龙族怪兽除外才能发动。在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张「相剑」卡或者1只幻龙族怪兽送去墓地。'),
(83308376, 'Swordsoul Punishment', '赫圣之相剑', '赫聖の相剣', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有同调怪兽存在的场合，以自己或者对方的场上·墓地1张卡为对象才能发动。那张卡除外。 ②：对方场上有仪式·融合·同调·超量·连接怪兽的其中任意种存在的场合，从自己墓地把1只同调怪兽除外才能发动。墓地的这张卡加入手卡。'),
(93850690, 'Swordsoul Sacred Summit', '大灵峰相剑门', '大霊峰相剣門', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「相剑」怪兽为对象才能发动（自己场上有同调怪兽存在的场合，也能作为代替以1只幻龙族怪兽为对象）。那只怪兽特殊召唤。 ②：这张卡被除外的场合，以自己场上1只「相剑」怪兽或者幻龙族怪兽为对象才能发动。那只怪兽的等级直到回合结束时上升或者下降1星。'),
(47710198, 'Swordsoul Sinister Sovereign - Qixing Longyuan', '相剑大邪－七星龙渊', '相剣大邪－七星龍淵', 'Synchro Monster', 'Wyrm', 'FIRE', 10, 2900, 2300, '调整＋调整以外的幻龙族怪兽1只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在怪兽区域存在的状态，自己把幻龙族同调怪兽同调召唤的场合才能发动。自己抽1张。 ②：对方把怪兽特殊召唤的场合才能发动。那之内的1只除外，给与对方1200伤害。 ③：对方把魔法·陷阱卡的效果发动时才能发动。那张卡除外，给与对方1200伤害。'),
(93490856, 'Swordsoul Strategist Longyuan', '相剑军师－龙渊', '相剣軍師－龍淵', 'Effect Monster', 'Wyrm', 'FIRE', 6, 1200, 2300, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡其他的1张「相剑」卡或者1只幻龙族怪兽丢弃才能发动。这张卡从手卡特殊召唤。那之后，可以在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。给与对方1200伤害。'),
(99137266, 'Swordsoul Strife', '忆念之相剑', '憶念の相剣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：卡被除外的场合才能发动。从自己的手卡·卡组·墓地以及自己·对方场上的表侧表示卡之中把1只幻龙族同调怪兽或者1张「相剑」卡除外。 ②：这张卡被除外的场合才能发动。在自己场上把1只「相剑衍生物」（幻龙族·调整·水·4星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(96633955, 'Swordsoul Supreme Sovereign - Chengying', '相剑大公－承影', '相剣大公－承影', 'Synchro Monster', 'Wyrm', 'WATER', 10, 3000, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：让这张卡的攻击力·守备力上升并让对方场上的怪兽的攻击力·守备力下降除外状态的卡数量×100。 ②：这张卡被效果破坏的场合，可以作为代替把自己墓地1张卡除外。 ③：卡被除外的场合才能发动。对方的场上以及墓地的卡各1张除外。'),
(50005633, 'Swordstalker', '复仇的潜行剑士', '復讐のソード・ストーカー', 'Normal Monster', 'Warrior', 'DARK', 6, 2000, 1600, '宿有被干掉的同伴怨念的怪兽。'),
(11682713, 'Sylvan Bladefender', '森罗的叶心棒 叶片', '森羅の葉心棒 ブレイド', 'Effect Monster', 'Plant', 'EARTH', 4, 1900, 700, '①：这张卡战斗破坏对方怪兽送去墓地时才能发动。自己卡组最上面的卡翻开，那张卡是植物族怪兽的场合，那只怪兽送去墓地。不是的场合，那张卡回到卡组最下面。 ②：卡组的这张卡被效果翻开送去墓地的场合才能发动。墓地的这张卡加入手卡。'),
(91650245, 'Sylvan Blessing', '森罗的恩惠', '森羅の恵み', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选1张手卡回到持有者卡组最上面或者最下面，从自己的手卡·墓地选1只名字带有「森罗」的怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不受这张卡以外的卡的效果影响，结束阶段时回到持有者卡组最上面或者最下面。'),
(82016179, 'Sylvan Charity', '森罗的施舍', '森羅の施し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组抽3张卡。那之后，把包含1张名字带有「森罗」的卡的手卡2张卡给对方观看，用喜欢的顺序回到卡组上面。手卡没有名字带有「森罗」的卡的场合，手卡全部给对方观看，用喜欢的顺序回到卡组上面。「森罗的施舍」在1回合只能发动1张。'),
(10753491, 'Sylvan Cherubsprout', '森罗的神芽 幼芽', '森羅の神芽 スプラウト', 'Effect Monster', 'Plant', 'LIGHT', 1, 100, 100, '这张卡特殊召唤成功时，可以从自己卡组上面把最多2张卡翻开。翻开的卡之中有植物族怪兽的场合，那些怪兽全部送去墓地。剩下的卡用喜欢的顺序回到卡组最下面。此外，卡组的这张卡被卡的效果翻开送去墓地的场合，可以从卡组把1只植物族·1星怪兽特殊召唤。「森罗的神芽 幼芽」的这个效果1回合只能使用1次。'),
(21903613, 'Sylvan Dancepione', '森罗舞娘 锋萄', '森羅の舞踏娘 ピオネ', 'Link Monster', 'Plant', 'WIND', NULL, 1200, NULL, '植物族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从自己卡组上面把最多3张卡翻开。那之中有植物族怪兽的场合，可以选那之内的最多2只特殊召唤。剩下的卡送去墓地。这个效果特殊召唤的怪兽不能作为连接素材。 ②：以自己墓地1只植物族怪兽为对象才能发动。这张卡所连接区的怪兽的等级直到回合结束时变成和作为对象的怪兽相同。');